/// <reference path="../pb_data/types.d.ts" />

/**
 * Разрыв связи тренера и клиента.
 *
 * Связь живёт полем trainer в записи клиента, а править свою запись вправе
 * только он сам — правило доступа у users так и звучит. Поэтому тренер,
 * убирая клиента у себя, рвал связь только на своём устройстве: на сервере
 * она оставалась, клиент продолжал числиться за ним, а подключить другого
 * тренера уже не мог.
 *
 * Отдельный обработчик решает это, не открывая чужие записи на запись
 * вообще: он проверяет, что зовущий — либо сам клиент, либо именно тот
 * тренер, за которым клиент числится сейчас. Чужого клиента отвязать
 * нельзя, даже зная его идентификатор.
 *
 * Про чужой идентификатор отвечаем одинаково в любом случае. Раньше коды
 * ответа различались — «такого нет» (404), «есть, но без тренера» (200) и
 * «есть, но не ваш» (403), — и обработчик тем самым отвечал на вопросы про
 * посторонних людей. Идентификатор клиента бывший тренер помнит всегда, так
 * что достаточно было раз в день дёрнуть эндпоинт, чтобы узнать, завёл ли
 * тот нового тренера. Это чужое дело, поэтому всё, что не своё, — один и тот
 * же отказ.
 */
routerAdd('POST', '/api/unlink', (e) => {
  const auth = e.auth
  if (!auth) {
    return e.json(401, { message: 'Нужно войти' })
  }

  const body = new DynamicModel({ client: '' })
  e.bindBody(body)

  const clientId = String(body.client || '').trim() || auth.id
  const mine = clientId === auth.id

  let client
  try {
    client = e.app.findRecordById('users', clientId)
  } catch {
    // Своя запись найдётся всегда, значит сюда попадает только чужой или
    // выдуманный идентификатор — и ответ у них общий.
    return e.json(403, { message: 'Это не ваш клиент' })
  }

  const trainerId = client.getString('trainer')

  // Свою связь человек рвёт всегда, даже если её уже нет: экран зовёт отвязку
  // и после того, как тренер снял связь со своей стороны, — падать на этом
  // нечему. Про себя же он ничего нового и не узнаёт.
  if (mine) {
    if (trainerId) {
      client.set('trainer', null)
      e.app.save(client)
    }
    return e.json(200, { ok: true })
  }

  // Чужую связь рвёт только тот тренер, за которым клиент числится сейчас.
  // Пустое поле сюда же: кто был тренером до этого, запись уже не помнит.
  if (!trainerId || trainerId !== auth.id) {
    return e.json(403, { message: 'Это не ваш клиент' })
  }

  client.set('trainer', null)
  e.app.save(client)

  return e.json(200, { ok: true })
})
